// Fuzzer stub for: uint16_t nl::Base64Encode(const uint8_t *in, uint16_t inLen, char *out)
// Requirements enforced:
// - out buffer sized to ((inLen + 2) / 3) * 4
// - in/out buffers do not overlap
// - in points to at least inLen readable bytes; out is writable
// - Property: returned length equals required encoded length
{
    // Generate input bytes from a fuzz string (arbitrary binary OK via .data())
    std::string inStr = FUZZ_PARAM_STR();
    uint16_t inLen = static_cast<uint16_t>(inStr.size());

    // Keep output size bounded for performance (< 2048 bytes)
    // maxOut = 2048 => maxIn ≈ (2048/4)*3 = 1536
    const uint16_t maxInForOut = 1536;
    if (inLen > maxInForOut) { inLen = maxInForOut; }

    const uint8_t *in = reinterpret_cast<const uint8_t *>(inStr.data());

    // Compute required output size and allocate a distinct buffer to avoid overlap
    uint16_t outRequired = static_cast<uint16_t>(((inLen + 2u) / 3u) * 4u);
    std::string outStr(outRequired, '\0');
    char *out = &outStr[0];

    // Call target
    uint16_t written = nl::Base64Encode(in, inLen, out);

    // Validate: must match required encoded length (no NUL terminator included)
    FUZZ_ASSERT(written == outRequired, "Base64Encode length mismatch vs required size");

    // Validation: Inputs and outputs are non-overlapping, output sized exactly as required, and return value asserted.
}

