// Fuzzer stub for: uint16_t nl::Base64Decode(const char *in, uint16_t inLen, uint8_t *out)
// Requirements handled:
// - out capacity >= inLen * 3 / 4
// - '=' padding only at end (we optionally sanitize to exercise success paths)
// - Supports in-place decode when out aliases in
// - Properly handles decode failure (UINT16_MAX) without assertions
{
    std::string raw = FUZZ_PARAM_STR();
    uint16_t inLen = static_cast<uint16_t>(raw.size());

    // Bound input for perf; keep <= 2048
    if (inLen > 2048u) { inLen = 2048u; }

    // Optionally sanitize to a multiple of 4 and add valid end padding to explore success paths
    unsigned int choose = *FUZZ_PARAM(unsigned int);
    bool sanitize = (choose & 1u) != 0u;
    std::string inStr = raw.substr(0, inLen);
    if (sanitize) {
        // trim to multiple of 4
        size_t m4 = (inStr.size() / 4u) * 4u;
        inStr.resize(m4);
        inLen = static_cast<uint16_t>(inStr.size());
        if (inLen >= 4u) {
            // choose padding count 0..2 and apply only at the end
            unsigned int pad = (choose >> 1) % 3u;
            if (pad > 0) {
                // ensure last block has proper '=' padding at very end
                for (unsigned int i = 0; i < pad; ++i) {
                    inStr[inStr.size() - 1 - i] = '=';
                }
            }
        }
    }

    // Compute max decoded size
    uint16_t outCap = static_cast<uint16_t>((inLen * 3u) / 4u);

    // Two modes: in-place or separate buffers
    bool inPlace = ((choose >> 3) & 1u) != 0u;
    uint16_t resultLen = 0;

    if (inPlace && inLen > 0) {
        // In-place: use a single mutable buffer containing input bytes
        std::vector<uint8_t> buf(inStr.begin(), inStr.end());
        const char *in = reinterpret_cast<const char *>(buf.data());
        uint8_t *out = buf.data();
        resultLen = nl::Base64Decode(in, inLen, out);
        if (resultLen != UINT16_MAX) {
            FUZZ_ASSERT(resultLen <= outCap, "Base64Decode wrote more than capacity in in-place mode");
        }
    } else {
        // Separate buffers: ensure non-overlap
        const char *in = inStr.c_str();
        std::vector<uint8_t> outVec(outCap == 0 ? 1 : outCap); // allocate at least 1 to ensure non-null pointer
        uint8_t *out = outVec.data();
        resultLen = nl::Base64Decode(in, inLen, out);
        if (resultLen != UINT16_MAX) {
            FUZZ_ASSERT(resultLen <= outCap, "Base64Decode wrote more than capacity");
        }
    }

    // Note: No bail on UINT16_MAX; it's a valid error return we accept.
    // Validation: Capacity respected, in-place path covered, and '=' placement sanitized in one branch.
}

