import os
import random
import struct
from typing import List

# This generator produces arbitrary binary data tailored to exercise Base64 encode paths.
# The fuzzer stubs use FUZZ_PARAM_STR() as the input byte array; we therefore return
# interesting raw byte sequences of varying lengths, including boundary conditions
# relevant to Base64 (multiples of 3, and off-by-one cases), as well as diverse content
# patterns to explore different internal code paths while remaining valid.

MAX_TOTAL_SIZE = 4096  # hard cap per requirements
# The stubs clamp input to 1536 bytes to keep output <= 2048, so we bias lengths within that.
FUZZ_MAX_IN = 1536


def _choose_length(rng: random.Random) -> int:
    # Focus on Base64-relevant boundaries and a spread of sizes up to FUZZ_MAX_IN
    interesting = [0, 1, 2, 3, 4, 5, 6, 7, 8, 15, 16, 31, 32, 63, 64, 127, 128, 255, 256, 511, 512, 1023, 1024, 1535, 1536]
    # Add multiples of 3 and nearby values
    for base in [3, 6, 9, 12, 24, 48, 96, 192, 384, 768, 1530]:
        for delta in [-2, -1, 0, 1, 2]:
            v = base + delta
            if 0 <= v <= FUZZ_MAX_IN:
                interesting.append(v)
    interesting = sorted(set(interesting))

    mode = rng.random()
    if mode < 0.6:
        return rng.choice(interesting)
    elif mode < 0.9:
        return rng.randint(0, FUZZ_MAX_IN)
    else:
        # Heavily biased to just under/at the clamp limit
        return rng.choice([FUZZ_MAX_IN, max(0, FUZZ_MAX_IN - 1), max(0, FUZZ_MAX_IN - 2)])


def _pattern_bytes(pattern: str, n: int, rng: random.Random) -> bytes:
    if n <= 0:
        return b""

    if pattern == "zeros":
        return b"\x00" * n
    if pattern == "ones":
        return b"\xFF" * n
    if pattern == "incr":
        return bytes((i % 256 for i in range(n)))
    if pattern == "decr":
        return bytes(((255 - i) % 256 for i in range(n)))
    if pattern == "alt01":
        return bytes(((i & 1) * 0xFF for i in range(n)))
    if pattern == "alt7F":
        return bytes((0x7F if (i & 1) else 0x80 for i in range(n)))
    if pattern == "printable":
        # Range of common ASCII visible characters
        chars = list(range(0x20, 0x7F))
        return bytes(rng.choice(chars) for _ in range(n))
    if pattern == "highbit":
        return bytes(rng.randint(0x80, 0xFF) for _ in range(n))
    if pattern == "random":
        return rng.randbytes(n)
    if pattern == "blocks":
        # Mix of small repeating blocks to trigger run-length patterns
        out = bytearray()
        while len(out) < n:
            block_len = rng.choice([1, 2, 3, 4, 8, 16, 32])
            block = rng.randbytes(block_len)
            reps = rng.randint(1, 8)
            out.extend(block * reps)
        return bytes(out[:n])
    if pattern == "words":
        # Compose from structured integers (endianness variations)
        out = bytearray()
        while len(out) + 4 <= n:
            val = rng.getrandbits(32)
            if rng.random() < 0.5:
                out.extend(struct.pack(">I", val))
            else:
                out.extend(struct.pack("<I", val))
        # tail
        rem = n - len(out)
        if rem:
            out.extend(rng.randbytes(rem))
        return bytes(out)
    return rng.randbytes(n)


def _splice_chunks(chunks: List[bytes], target_len: int, rng: random.Random) -> bytes:
    if not chunks:
        return b""
    out = bytearray()
    while len(out) < target_len and chunks:
        chunk = rng.choice(chunks)
        if not chunk:
            continue
        take = min(len(chunk), target_len - len(out))
        # sometimes take a prefix/suffix/middle
        mode = rng.randint(0, 3)
        if mode == 0:
            out.extend(chunk[:take])
        elif mode == 1:
            out.extend(chunk[-take:])
        else:
            if take == len(chunk):
                out.extend(chunk)
            else:
                start = rng.randint(0, len(chunk) - take)
                out.extend(chunk[start:start + take])
    if len(out) < target_len:
        out.extend(bytes(target_len - len(out)))
    return bytes(out)


def _insert_edge_sentinels(buf: bytearray, rng: random.Random) -> None:
    # Insert edge-case bytes at strategic positions to diversify triplets for Base64
    sentinels = [0x00, 0x01, 0x02, 0x7F, 0x80, 0xFE, 0xFF]
    pos_list = [0, 1, 2, 3, 7, 8, 15, 16, 31, 32, len(buf) - 1]
    for pos in pos_list:
        if 0 <= pos < len(buf) and rng.random() < 0.5:
            buf[pos] = rng.choice(sentinels)


def _ensure_triplet_boundaries(buf: bytearray, rng: random.Random) -> None:
    # For some cases, make length mod 3 specific to test padding behavior
    # This function only tweaks a couple of bytes without changing length.
    if not buf:
        return
    # Nudge around boundaries to create 24-bit patterns
    for i in range(0, min(len(buf), 96), 3):
        if rng.random() < 0.2 and i + 2 < len(buf):
            # Compose a recognizable 3-byte block like 0x00 0xFF 0xAA, etc.
            patterns = [
                (0x00, 0x00, 0x00),
                (0xFF, 0xFF, 0xFF),
                (0x00, 0xFF, 0xAA),
                (0x12, 0x34, 0x56),
                (0xDE, 0xAD, 0xBE),
                (0xBA, 0xAD, 0xF0),
            ]
            a, b, c = rng.choice(patterns)
            buf[i], buf[i + 1], buf[i + 2] = a, b, c


def generate(seed: int) -> bytes:
    rng = random.Random(seed)

    # Decide overall length, with focus on Base64 padding cases
    length = _choose_length(rng)

    # If we generate more than MAX_TOTAL_SIZE, clamp
    length = min(length, MAX_TOTAL_SIZE)

    # Choose a primary pattern and optionally blend with others
    patterns = [
        "zeros", "ones", "incr", "decr", "alt01", "alt7F",
        "printable", "highbit", "random", "blocks", "words",
    ]

    primary = rng.choice(patterns)
    base = _pattern_bytes(primary, length, rng)

    # Blend in up to two auxiliary chunks to create heterogeneous content
    chunks: List[bytes] = [base]
    aux_count = rng.randint(0, 2)
    for _ in range(aux_count):
        aux_pat = rng.choice([p for p in patterns if p != primary])
        # Use partial lengths for variety
        aux_len = rng.randint(0, length)
        chunks.append(_pattern_bytes(aux_pat, aux_len, rng))

    data = bytearray(_splice_chunks(chunks, length, rng))

    # Sprinkle edge-case bytes and recognizable triplet patterns
    _insert_edge_sentinels(data, rng)
    _ensure_triplet_boundaries(data, rng)

    # Optionally adjust length to enforce specific mod-3 to test '=' padding in output
    # We don't exceed FUZZ_MAX_IN and not exceed MAX_TOTAL_SIZE
    if length > 0 and rng.random() < 0.5:
        target_mod = rng.choice([0, 1, 2])
        cur_mod = len(data) % 3
        if cur_mod != target_mod:
            delta = (target_mod - cur_mod) % 3
            # Add delta bytes using random content (keeps validity as arbitrary bytes)
            add_n = min(delta, FUZZ_MAX_IN - len(data), MAX_TOTAL_SIZE - len(data))
            if add_n > 0:
                data.extend(rng.randbytes(add_n))

    # Final clamp to fuzzer expectation
    if len(data) > FUZZ_MAX_IN:
        del data[FUZZ_MAX_IN:]

    return bytes(data)
